<script setup lang="ts">
import {ref,computed,watch,nextTick,onMounted,onBeforeUnmount} from 'vue';
import {request,ApiError,type Guest} from '../lib/api';
import {streamLobby,mergeLobby,retractable,type LobbyMessage} from '../lib/lobby';
const props=defineProps<{foreground:boolean;me:Guest}>();
const emit=defineEmits<{(e:'auth-expired'):void;(e:'unread',count:number):void}>();
const syncNotice=ref('');
const messages=ref<LobbyMessage[]>([]),draft=ref(''),error=ref(''),connection=ref('connecting'),online=ref(0),unread=ref(0),mutedUntil=ref<string|null>(null),now=ref(Date.now());
const timeline=ref<HTMLElement|null>(null),composer=ref<HTMLTextAreaElement|null>(null),atBottom=ref(true),hasOlder=ref(true),loadingOlder=ref(false),sending=ref(false),initial=ref(false),showEmoji=ref(false);
type Pending={id:string;text:string;status:'sending'|'failed';error:string};const pending=ref<Pending[]>([]);
const modal=ref<{type:'retract'|'remove'|'mute'|'mutes';message?:LobbyMessage}|null>(null),modalBusy=ref(false),modalError=ref(''),muteHours=ref(1),mutes=ref<{id:string;username:string;until:string}[]>([]);
const emojis=['🐟','😂','＋1'],quick=['先摸为敬 🐟','收到，但灵魂没收到','这班先上到这里'],emojiPicker=['🐟','😂','😭','🙃','🥲','🤝','☕','🍚','🫠','👍','🎉','👀'];
let disposed=false,controller:AbortController|undefined,retry:ReturnType<typeof setTimeout>|undefined,flushTimer:ReturnType<typeof setTimeout>|undefined,clock:ReturnType<typeof setInterval>|undefined,epoch=0,offset=0,retries=0,refreshing=false,needState=false,reading=false;
const dirty=new Set<number>();let syncing=false,followAfterSync=false;
const muted=computed(()=>!!mutedUntil.value&&Date.parse(mutedUntil.value)>now.value+offset);
const visibleNow=()=>props.foreground&&document.visibilityState==='visible';
const lastID=()=>messages.value.length?messages.value[messages.value.length-1].id:0;
function failure(e:unknown){if(disposed)return;if(e instanceof ApiError&&(e.status===401||e.status===0)){if(e.status===401)emit('auth-expired');return;}error.value=(e as Error).message;}
function time(s:string){return new Date(s).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false});}
function date(s:string){return new Date(s).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'});}
function avatar(id:string){return ['🐟','🍞','🍵','🐼','🍄','🐸','🥔','🌱'][parseInt(id.slice(0,4),16)%8||0];}
function own(m:LobbyMessage){return m.account_id===props.me.id;}
function canRetract(m:LobbyMessage){return retractable(m,props.me.id,now.value+offset);}
async function state(){if(refreshing){needState=true;return;}refreshing=true;try{const s=await request<{unread:number;online:number;muted_until:string|null;server_time:string}>('/lobby/state');if(disposed)return;unread.value=s.unread;online.value=s.online;mutedUntil.value=s.muted_until;offset=Date.parse(s.server_time)-Date.now();emit('unread',s.unread);}catch(e){failure(e);}finally{refreshing=false;if(needState&&!disposed){needState=false;void state();}}}
async function markRead(){if(reading||!visibleNow()||!atBottom.value||!initial.value||!lastID())return;reading=true;const id=lastID();try{await request('/lobby/read','POST',{id});if(!disposed)await state();}catch(e){failure(e);}finally{reading=false;if(!disposed&&lastID()>id&&visibleNow()&&atBottom.value)void markRead();}}
async function bottom(){await nextTick();if(disposed||!visibleNow())return;const el=timeline.value;if(el)el.scrollTop=el.scrollHeight;atBottom.value=true;void markRead();}
function scrolled(){const el=timeline.value;if(!el)return;const before=atBottom.value;atBottom.value=el.scrollHeight-el.scrollTop-el.clientHeight<55;if(atBottom.value&&!before)void markRead();}
async function apply(list:LobbyMessage[],follow:boolean){if(disposed)return;messages.value=mergeLobby(messages.value,list);pending.value=pending.value.filter(p=>!list.some(m=>own(m)&&m.request_id===p.id));if(follow&&visibleNow())await bottom();}
async function sync(){if(syncing)return;syncing=true;try{
 let ids=messages.value.map(m=>m.id);const newest=lastID(),first=await request<{messages:LobbyMessage[]}>('/lobby/messages');if(disposed)return;
 if(newest&&first.messages.length===50&&Math.min(...first.messages.map(m=>m.id))>newest){messages.value=[];ids=[];hasOlder.value=true;syncNotice.value='离线期间有较多新消息，已同步最近50条；向上翻可以查看完整历史。';}
 if(!initial.value){hasOlder.value=first.messages.length===50;initial.value=true;}
 await apply(first.messages,atBottom.value);
 for(let i=0;i<ids.length;i+=100){const d=await request<{messages:LobbyMessage[]}>('/lobby/messages?ids='+ids.slice(i,i+100).join(','));if(disposed)return;await apply(d.messages,false);}
 await state();if(visibleNow()&&atBottom.value)await markRead();connection.value='online';retries=0;
 }catch(e){failure(e);controller?.abort();}finally{syncing=false;if(followAfterSync&&!disposed){followAfterSync=false;void sync();}}}
async function flush(){flushTimer=undefined;if(disposed)return;const ids=[...dirty].slice(0,100);ids.forEach(id=>dirty.delete(id));try{if(ids.length){const d=await request<{messages:LobbyMessage[]}>('/lobby/messages?ids='+ids.join(','));await apply(d.messages,atBottom.value);}await state();}catch(e){failure(e);controller?.abort();}if(dirty.size&&!disposed)schedule();}
function schedule(){if(!flushTimer)flushTimer=setTimeout(()=>void flush(),120);}
async function connect(){if(disposed)return;const n=++epoch;controller?.abort();clearTimeout(retry);const c=new AbortController();controller=c;connection.value='connecting';try{await streamLobby(visibleNow(),c.signal,e=>{if(disposed||n!==epoch)return;if(typeof e.data.online==='number')online.value=e.data.online;if(e.event==='ready'){if(syncing)followAfterSync=true;else void sync();}if(e.event==='change'){if(e.data.id>0)dirty.add(e.data.id);schedule();}});}catch(e){if(!disposed&&n===epoch&&e instanceof ApiError&&(e.status===401||e.status===0)){failure(e);return;}}if(!disposed&&n===epoch){connection.value='offline';retry=setTimeout(()=>void connect(),Math.min(15000,1000*2**Math.min(retries++,4)));}}
function visibility(){void connect();if(visibleNow()&&atBottom.value)void bottom();}
async function older(){if(loadingOlder.value||!hasOlder.value||!messages.value.length)return;loadingOlder.value=true;const el=timeline.value,oldHeight=el?.scrollHeight||0,oldTop=el?.scrollTop||0;try{const d=await request<{messages:LobbyMessage[]}>('/lobby/messages?before='+messages.value[0].id);if(disposed)return;hasOlder.value=d.messages.length===50;messages.value=mergeLobby(messages.value,d.messages);await nextTick();if(el)el.scrollTop=oldTop+el.scrollHeight-oldHeight;}catch(e){failure(e);}finally{if(!disposed)loadingOlder.value=false;}}
async function send(existing?:Pending){if(sending.value||muted.value||disposed)return;const text=existing?existing.text:draft.value.trim();if(!text||text.length>1000)return;if(!existing&&pending.value.length>=10){error.value='先处理未发送成功的消息，再继续聊。';return;}
 const p=existing||{id:crypto.randomUUID(),text,status:'sending' as const,error:''};p.status='sending';p.error='';if(!existing){pending.value.push(p);draft.value='';showEmoji.value=false;}sending.value=true;error.value='';composer.value?.focus({preventScroll:true});void bottom();
 try{const d=await request<{id:number}>('/lobby/messages','POST',{request_id:p.id,content:p.text});const result=await request<{messages:LobbyMessage[]}>('/lobby/messages?ids='+d.id);if(disposed)return;await apply(result.messages,true);await state();}catch(e){if(disposed)return;p.status='failed';p.error=(e as Error).message;failure(e);void state();}finally{if(!disposed){sending.value=false;composer.value?.focus({preventScroll:true});}}}
function keyboard(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();void send();}}
function addText(s:string){draft.value=(draft.value+s).slice(0,1000);composer.value?.focus({preventScroll:true});}
const reacting=new Set<string>();
async function react(m:LobbyMessage,emoji:string){const key=m.id+emoji;if(reacting.has(key)||muted.value)return;reacting.add(key);try{await request('/lobby/messages/'+m.id+'/reaction','POST',{emoji,active:!m.reactions.some(x=>x.emoji===emoji&&x.mine)});dirty.add(m.id);schedule();}catch(e){failure(e);}finally{reacting.delete(key);}}
function reaction(m:LobbyMessage,emoji:string){return m.reactions.find(x=>x.emoji===emoji);}
let focusBefore:HTMLElement|null=null;
function closeModal(){if(modalBusy.value)return;modal.value=null;focusBefore?.focus();}
async function openModal(type:'retract'|'remove'|'mute'|'mutes',m?:LobbyMessage){focusBefore=document.activeElement as HTMLElement;modal.value={type,message:m};modalError.value='';muteHours.value=1;await nextTick();document.getElementById('lobby-modal-cancel')?.focus();if(type==='mutes')try{const d=await request<{items:typeof mutes.value}>('/admin/lobby/mutes');if(!disposed)mutes.value=d.items;}catch(e){if(!disposed)modalError.value=(e as Error).message;}}
function modalKeys(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const buttons=Array.from(document.querySelectorAll<HTMLButtonElement>('#lobby-modal button:not([disabled])')),first=buttons[0],last=buttons[buttons.length-1];if(!first){e.preventDefault();return;}if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
async function moderate(unmute?:string){if(modalBusy.value||!modal.value)return;modalBusy.value=true;modalError.value='';const action=modal.value;try{
 if(unmute)await request('/lobby/messages/0/moderate','POST',{action:'mute',account_id:unmute,hours:0});
 else if(action.type==='retract')await request('/lobby/messages/'+action.message!.id+'/retract','POST',{});
 else if(action.type==='remove')await request('/lobby/messages/'+action.message!.id+'/moderate','POST',{action:'remove'});
 else if(action.type==='mute')await request('/lobby/messages/0/moderate','POST',{action:'mute',account_id:action.message!.account_id,hours:muteHours.value});
 if(disposed)return;if(unmute){mutes.value=mutes.value.filter(x=>x.id!==unmute);}else{modal.value=null;focusBefore?.focus();}if(action.message){dirty.add(action.message.id);schedule();}void state();
 }catch(e){if(!disposed){modalError.value=(e as Error).message;failure(e);}}finally{if(!disposed)modalBusy.value=false;}}
watch(()=>props.foreground,()=>{if(!props.foreground&&!modalBusy.value)modal.value=null;visibility();});
onMounted(()=>{void connect();document.addEventListener('visibilitychange',visibility);clock=setInterval(()=>now.value=Date.now(),5000);});
onBeforeUnmount(()=>{disposed=true;epoch++;controller?.abort();clearTimeout(retry);clearTimeout(flushTimer);clearInterval(clock);document.removeEventListener('visibilitychange',visibility);});
</script>
<template>
<view class="lobby">
 <view class="lobby-heading"><view><text class="eyebrow">LOUNGE / 工位之外的公共茶水间</text><text class="title">摸鱼大厅 <text>🐟</text></text><text class="subtitle">此处允许废话，不要求形成会议纪要。</text></view><view class="presence"><text class="online-dot"/>{{online}} 人正在摸鱼</view></view>
 <view class="privacy"><text>公共大厅 · 消息对所有已登录用户可见，请勿发送密码或私人资料。</text><button v-if="me.is_admin" @click="openModal('mutes')">禁言管理</button></view>
 <view class="fish-tank">
 <view class="tank-top"><text>茶水间实时广播</text><text :class="['connection',connection]">{{connection==='online'?'● 已连上鱼塘':connection==='connecting'?'◌ 正在连接…':'◌ 鱼塘信号不太好，正在重连'}}</text></view>
 <component :is="'div'" ref="timeline" class="timeline" @scroll="scrolled" tabindex="0" aria-label="大厅聊天记录">
 <text v-if="syncNotice" class="history-end">{{syncNotice}}</text>
 <button v-if="hasOlder&&messages.length" class="history" :disabled="loadingOlder" @click="older">{{loadingOlder?'正在翻旧泡泡…':'↑ 看更早的聊天'}}</button><text v-else-if="messages.length" class="history-end">鱼塘的故事，从这里开始</text>
 <view v-if="!messages.length" class="empty"><text>🐟</text><text>{{initial?'鱼塘暂时平静，你来吐第一个泡泡。':'正在接通茶水间…'}}</text></view>
 <template v-for="(m,i) in messages" :key="m.id"><view v-if="i===0||date(m.created_at)!==date(messages[i-1].created_at)" class="day-divider">{{date(m.created_at)}} · 北京时间</view>
 <view v-if="m.status!=='active'" class="withdrawn">{{m.status==='removed'?'管理员移除了一条消息':m.username+' 撤回了一条消息'}}</view>
 <view v-else :class="['chat-row',{mine:own(m)}]"><view class="avatar">{{avatar(m.account_id)}}</view><view class="message-body"><view class="message-meta"><text>{{own(m)?'你':m.username}}</text><text v-if="m.username==='cole'" class="cole-label">店长</text><text>{{time(m.created_at)}}</text></view><view class="bubble"><text selectable>{{m.content}}</text></view><view class="message-tools"><button v-for="emoji in emojis" :key="emoji" :class="['reaction',{picked:reaction(m,emoji)?.mine}]" :disabled="muted" @click="react(m,emoji)" :aria-label="emoji+' 回应'" :aria-pressed="!!reaction(m,emoji)?.mine">{{emoji}} <text>{{reaction(m,emoji)?.count||''}}</text></button><button v-if="canRetract(m)" @click="openModal('retract',m)">撤回</button><template v-if="me.is_admin"><button @click="openModal('remove',m)">移除</button><button v-if="!own(m)" @click="openModal('mute',m)">禁言</button></template></view></view></view>
 </template>
 <view v-for="p in pending" :key="p.id" class="chat-row mine pending"><view class="avatar">{{avatar(me.id)}}</view><view class="message-body"><view class="message-meta">你</view><view class="bubble"><text selectable>{{p.text}}</text></view><text v-if="p.status==='sending'" class="pending-label">正在吐泡泡…</text><view v-else class="pending-failed"><text>{{p.error}}</text><button :disabled="sending||muted" @click="send(p)">重试</button><button @click="pending=pending.filter(x=>x.id!==p.id)">忽略</button></view></view></view>
 </component>
 <button v-if="!atBottom" class="new-messages" @click="bottom">{{unread?'有 '+unread+' 条未读摸鱼情报':'回到最新聊天'}} ↓</button>
 <view class="composer-area"><text v-if="error" class="error" role="alert">{{error}}</text><text v-if="muted" class="mute-note">暂时进入潜水模式，禁言至 {{date(mutedUntil!)}} {{time(mutedUntil!)}}。仍可查看聊天。</text><view class="quick"><button v-for="q in quick" :key="q" :disabled="muted" @click="addText(q)">{{q}}</button></view>
 <view class="input-row"><component :is="'textarea'" ref="composer" class="chat-input" :value="draft" @input="draft=($event.target as HTMLTextAreaElement).value" @keydown="keyboard" maxlength="1000" rows="3" :disabled="muted" placeholder="来都来了，说两句废话……" aria-label="大厅消息"/><button class="send" :disabled="sending||muted||!draft.trim()||draft.length>1000" @click="send()">{{sending?'发送中':'发送 ↗'}}</button></view><view class="composer-footer"><button @click="showEmoji=!showEmoji" :aria-expanded="showEmoji" :disabled="muted">☺ 表情</button><text>{{draft.length}} / 1000 · Enter 发送，Shift＋Enter 换行</text></view><view v-if="showEmoji" class="emoji-picker"><button v-for="e in emojiPicker" :key="e" @click="addText(e)">{{e}}</button></view>
 </view></view>
 <text class="bottom-note">公共聊天，不是匿名树洞。文明摸鱼，别让别人替你的情绪加班。</text>
 <view v-if="modal" class="lobby-overlay" @click.self="closeModal" @keydown="modalKeys"><view id="lobby-modal" class="lobby-modal" role="dialog" aria-modal="true" aria-labelledby="lobby-modal-title"><text class="eyebrow">鱼塘秩序维护站</text><text id="lobby-modal-title" class="modal-title">{{modal.type==='mutes'?'正在潜水的顾客':modal.type==='mute'?'让这位顾客冷静一下？':modal.type==='retract'?'撤回这个泡泡？':'移除这条消息？'}}</text><text v-if="modal.message" class="modal-preview">{{modal.message.username}}：{{modal.message.content}}</text><view v-if="modal.type==='mute'" class="mute-options"><button v-for="h in [1,24,168]" :key="h" :class="{selected:muteHours===h}" @click="muteHours=h">{{h===168?'7天':h+'小时'}}</button></view><template v-if="modal.type==='mutes'"><text v-if="!mutes.length" class="bottom-note">暂无禁言中的顾客。</text><view v-for="u in mutes" :key="u.id" class="muted-user"><view><text>{{u.username}}</text><text>{{date(u.until)}} {{time(u.until)}} 到期</text></view><button :disabled="modalBusy" @click="moderate(u.id)">解除禁言</button></view></template><text v-else class="bottom-note">{{modal.type==='mute'?'禁言期间可阅读，不能发言或回应；可在禁言管理中提前解除。':'操作后会同步到所有人的大厅，原文无法恢复。'}}</text><text v-if="modalError" class="error">{{modalError}}</text><view class="modal-actions"><button id="lobby-modal-cancel" :disabled="modalBusy" @click="closeModal">{{modal.type==='mutes'?'关闭':'先不操作'}}</button><button v-if="modal.type!=='mutes'" class="confirm" :disabled="modalBusy" @click="moderate()">{{modalBusy?'处理中…':'确认'+(modal.type==='mute'?'禁言':modal.type==='retract'?'撤回':'移除')}}</button></view></view></view>
</view>
</template>
<style scoped>
